script:
page.policyNoError="";
page.policyFetched = false;

if (!page.policyNo) {

    page.policyNoError = "Policy No is required";
    return;
}

bh.local.policyApiUrl =
    bh.system.environment.properties.ssdURL +
    "policy/" +page.policyNo;

const response = bh.local.response;

page.policyNoError = "";

if (!response || !response.policy_no
) {
console.log("11111",response)
    page.policyFetched = false;

    page.policyNoError = "Policy not found.";

    page.policyNumber = "";
    page.customerName = "";
    page.customerEmail = "";
    page.vehicleRegistration = "";
    page.vehicleType = "";
    page.yearOfManufacture = "";
    page.idv = "";
    page.policyStartDate = "";
    page.policyEndDate = "";
    page.policyStatus = "";

} else {

    page.policyFetched = true;

    // Policy details
    page.policyNumber = response.policy_no;
    page.policyStatus = response.status;

    // Customer details
    page.customerName = response.customer_name;
    page.customerEmail = response.customer_email;

    // Vehicle details
    page.vehicleRegistration = response.vehicle_reg;
    page.vehicleType = response.vehicle_type;
    page.yearOfManufacture = response.year_of_manufacture;

    // IDV
    page.idv = response.idv;

    // Policy period
    page.policyStartDate = response.policy_start_date;
    page.policyEndDate = response.policy_end_date;
}

page.today = new Date();


page.policyFetched = false;
page.isDisabled = true;
page.policyLoading = false;
page.submitting = false;
page.submitted = false;
page.submitSuccess = false;

page.submitError = "";
page.submitMessage = "";
page.validationErrors = {};


// ============================================================
// MOTOR OD MASTER DATA
// ============================================================

page.partGroups = [];
page.lossTypes = [];


// ============================================================
// LOAD MASTER DATA RESPONSE
// ============================================================

if (
    bh.local.records
) {

    var masterData = bh.local.records;


    // ========================================================
    // PART GROUPS
    // ========================================================

    if (Array.isArray(masterData.partGroups)) {

        page.partGroups = masterData.partGroups

            .map(function (item) {

                return {
                    label: item["Part Group"],
                    value: item["Part Group Code"]
                };

            });

    }


    // ========================================================
    // LOSS TYPES
    // ========================================================

    if (Array.isArray(masterData.lossTypes)) {

        page.lossTypes = masterData.lossTypes

            .map(function (item) {

                return {
                    label: item["Loss Type"],
                    value: item["Loss Code"]
                };

            });

    }


} else {

    console.log(
        "Motor OD master data is not available or API response is unsuccessful"
    );

}




// ============================================================
// CLAIM FORM DEFAULT VALUES
// ============================================================

page.policyNumber = "";
page.customerName = "";
page.customerEmail = "";
page.vehicleRegistration = "";
page.vehicleType = "";
page.yearOfManufacture = "";
page.idv = "";

page.policyStartDate = "";
page.policyEndDate = "";
page.policyStatus = "";

page.dateOfLoss = "";

page.lossType = "";
page.primaryDamageGroup = "";

page.estimatedPartsCost = "";

page.garageType = "";

page.firFiled = "";
page.validLicence = "";

page.lossDescription = "";


// ============================================================
// FIELD ERRORS
// ============================================================

page.policyNoError = "";
page.dateOfLossError = "";
page.lossTypeError = "";
page.primaryDamageGroupError = "";
page.estimatedPartsCostError = "";
page.garageTypeError = "";

page.lossDescriptionError = "";
page.today = new Date();
console.log("page.partGroups",page.partGroups)
console.log("page.lossTypes",page.lossTypes)

const f = bh.input.fieldName;
const v = page[f];

const s =
    v == null
        ? ""
        : v.toString().trim();

let e = "";


/* ============================================================
 * POLICY NUMBER
 * ============================================================ */

if (f === "policyNo") {

    if (!s) {

        e = "Policy Number is required";

    }


}


/* ============================================================
 * DATE OF LOSS
 * ============================================================ */

else if (f === "dateOfLoss") {

    if (!s) {

        e = "Date of Loss is required";

    }
    else {

        const lossDate = new Date(v);

        if (
            isNaN(lossDate.getTime())
        ) {

            e = "Enter a valid Date of Loss";

        }

        else if (
            lossDate > new Date()
        ) {

            e = "Date of Loss cannot be in the future";

        }

        else if (
            page.policyFetched &&
            page.policyStartDate &&
            page.policyEndDate
        ) {

            const policyStart =
                new Date(page.policyStartDate);

            const policyEnd =
                new Date(page.policyEndDate);

            if (
                lossDate < policyStart ||
                lossDate > policyEnd
            ) {

                e =
                    "Date of Loss must be within the policy period";

            }

        }

    }

}


/* ============================================================
 * LOSS TYPE
 * ============================================================ */

else if (f === "lossType") {

    if (!s) {

        e = "Loss Type is required";

    }

}


/* ============================================================
 * PRIMARY DAMAGE GROUP
 * ============================================================ */

else if (f === "primaryDamageGroup") {

    if (!s) {

        e = "Primary Damage Group is required";

    }

}


/* ============================================================
 * ESTIMATED PARTS COST
 * ============================================================ */

else if (f === "estimatedPartsCost") {

    if (!s) {

        e =
            "Estimated Parts Cost is required";

    }

    else if (
        !isFinite(Number(v)) ||
        Number(v) <= 0
    ) {

        e =
            "Estimated Parts Cost must be greater than 0";

    }

    else if (
        page.idv &&
        Number(v) > Number(page.idv)
    ) {

        e =
            "Estimated Parts Cost cannot exceed IDV";

    }

}


/* ============================================================
 * GARAGE TYPE
 * ============================================================ */

else if (f === "garageType") {

    if (!s) {

        e = "Garage Type is required";

    }

    else if (
        s !== "NETWORK" &&
        s !== "NON_NETWORK"
    ) {

        e =
            "Select a valid Garage Type";

    }

}



/* ============================================================
 * LOSS DESCRIPTION
 * ============================================================ */

else if (f === "lossDescription") {

    if (!s) {

        e =
            "Loss Description is required";

    }

    else if (
        s.length > 200
    ) {

        e =
            "Loss Description cannot exceed 200 characters";

    }

}


/* ============================================================
 * UPDATE FIELD ERROR
 * ============================================================ */

page[f + "Error"] = e;


/* ============================================================
 * ENSURE VALIDATION ERROR OBJECT
 * ============================================================ */

if (
    !page.validationErrors
) {

    page.validationErrors = {};

}


/* ============================================================
 * UPDATE VALIDATION ERRORS
 * ============================================================ */

if (e) {

    page.validationErrors[f] = e;

}
else {

    page.validationErrors[f] = "";

    delete page.validationErrors[f];

}


/* ============================================================
 * RECALCULATE FORM VALIDITY
 * ============================================================ */

let hasErrors = false;

Object.keys(
    page.validationErrors || {}
).forEach(
    function(key) {

        const error =
            page.validationErrors[key];

        if (
            error &&
            error.toString().trim() !== ""
        ) {

            hasErrors = true;

        }

    }
);


/* ============================================================
 * FORM VALID STATE
 * ============================================================ */

bh.local.isValid =
    !hasErrors;


/* ============================================================
 * DEBUG
 * ============================================================ */

console.log(
    "===================================="
);

console.log(
    "Field:",
    f
);

console.log(
    "Value:",
    s
);

console.log(
    "Field Error:",
    e
);

console.log(
    "Page Error:",
    page[f + "Error"]
);

console.log(
    "Validation Errors:",
    page.validationErrors
);

console.log(
    "Form Valid:",
    bh.local.isValid
);

console.log(
    "===================================="
);

 /* ============================================================
  * INITIALIZE SUBMISSION STATE
  * ============================================================ */

page.submitted = false;
page.submitError = "";
page.submitSuccess = false;
page.submitting = false;

console.log("Motor OD Claim page:", page);


/* ============================================================
 * INITIALIZE VALIDATION
 * ============================================================ */

if (!page.validationErrors) {

    page.validationErrors = {};

}

page.validationErrors = {};

let valid = true;


/* ============================================================
 * SET ERROR FUNCTION
 * ============================================================ */

function setError(field, message) {

    page[field + "Error"] =
        message || "";

    page.validationErrors[field] =
        message || "";

    if (message) {

        valid = false;

    }

}


/* ============================================================
 * CLEAR PREVIOUS FIELD ERRORS
 * ============================================================ */

const fields = [

    "policyNo",
    "dateOfLoss",
    "lossType",
    "primaryDamageGroup",
    "estimatedPartsCost",
    "garageType",

    "lossDescription"

];


fields.forEach(function(field) {

    page[field + "Error"] = "";

});


/* ============================================================
 * POLICY NUMBER
 * ============================================================ */

const policyNumber =
    (page.policyNo || "")
        .toString()
        .trim();


if (!policyNumber) {

    setError(
        "policyNo",
        "Policy Number is required"
    );

}
else if (
    !page.policyFetched
) {

    setError(
        "policyNo",
        "Fetch a valid policy before submitting"
    );

}


/* ============================================================
 * DATE OF LOSS
 * ============================================================ */

if (!page.dateOfLoss) {

    setError(
        "dateOfLoss",
        "Date of Loss is required"
    );

}
else {

    const lossDate =
        new Date(page.dateOfLoss);


    /* --------------------------------------------------------
     * INVALID DATE
     * -------------------------------------------------------- */

    if (
        isNaN(
            lossDate.getTime()
        )
    ) {

        setError(
            "dateOfLoss",
            "Enter a valid Date of Loss"
        );

    }


    /* --------------------------------------------------------
     * FUTURE DATE
     * -------------------------------------------------------- */

    else if (
        lossDate > new Date()
    ) {

        setError(
            "dateOfLoss",
            "Date of Loss cannot be in the future"
        );

    }


    /* --------------------------------------------------------
     * POLICY PERIOD
     * -------------------------------------------------------- */

    else if (
        page.policyFetched &&
        page.policyStartDate &&
        page.policyEndDate
    ) {

        const policyStart =
            new Date(
                page.policyStartDate
            );

        const policyEnd =
            new Date(
                page.policyEndDate
            );


        if (
            lossDate < policyStart ||
            lossDate > policyEnd
        ) {

            setError(
                "dateOfLoss",
                "Date of Loss must be within the policy period"
            );

        }

    }

}


/* ============================================================
 * LOSS TYPE
 * ============================================================ */

const lossType =
    (page.lossType || "")
        .toString()
        .trim();


const validLossTypes =
    (page.lossTypes || [])
        .map(function(item) {

            return item.value;

        });


if (!lossType) {

    setError(
        "lossType",
        "Loss Type is required"
    );

}
else if (
    validLossTypes.indexOf(
        lossType
    ) === -1
) {

    setError(
        "lossType",
        "Select a valid Loss Type"
    );

}


/* ============================================================
 * PRIMARY DAMAGE GROUP
 * ============================================================ */

const primaryDamageGroup =
    (page.primaryDamageGroup || "")
        .toString()
        .trim();


const validPartGroups =
    (page.partGroups || [])
        .map(function(item) {

            return item.value;

        });


if (!primaryDamageGroup) {

    setError(
        "primaryDamageGroup",
        "Primary Damage Group is required"
    );

}
else if (
    validPartGroups.indexOf(
        primaryDamageGroup
    ) === -1
) {

    setError(
        "primaryDamageGroup",
        "Select a valid Primary Damage Group"
    );

}


/* ============================================================
 * ESTIMATED PARTS COST
 * ============================================================ */

const estimatedPartsCost =
    page.estimatedPartsCost;


if (
    estimatedPartsCost === null ||
    estimatedPartsCost === undefined ||
    estimatedPartsCost === ""
) {

    setError(
        "estimatedPartsCost",
        "Estimated Parts Cost is required"
    );

}
else if (
    !isFinite(
        Number(estimatedPartsCost)
    ) ||
    Number(estimatedPartsCost) <= 0
) {

    setError(
        "estimatedPartsCost",
        "Estimated Parts Cost must be greater than 0"
    );

}
else if (
    page.idv &&
    Number(estimatedPartsCost) >
    Number(page.idv)
) {

    setError(
        "estimatedPartsCost",
        "Estimated Parts Cost cannot exceed IDV"
    );

}


/* ============================================================
 * GARAGE TYPE
 * ============================================================ */

const garageType =
    (page.garageType || "")
        .toString()
        .trim();


if (!garageType) {

    setError(
        "garageType",
        "Garage Type is required"
    );

}
else if (
    garageType !== "NETWORK" &&
    garageType !== "NON_NETWORK"
) {

    setError(
        "garageType",
        "Select a valid Garage Type"
    );

}




/* ============================================================
 * LOSS DESCRIPTION
 * ============================================================ */

const lossDescription =
    (page.lossDescription || "")
        .toString()
        .trim();


if (!lossDescription) {

    setError(
        "lossDescription",
        "Loss Description is required"
    );

}
else if (
    lossDescription.length > 200
) {

    setError(
        "lossDescription",
        "Loss Description cannot exceed 200 characters"
    );

}


/* ============================================================
 * FINAL VALIDATION RESULT
 * ============================================================ */

bh.local.isValid =
    valid;


/* ============================================================
 * DEBUG
 * ============================================================ */

console.log(
    "========================================"
);

console.log(
    "MOTOR OD CLAIM VALIDATION RESULT:",
    bh.local.isValid
);

console.log(
    "VALID:",
    valid
);

console.log(
    "VALIDATION ERRORS:",
    page.validationErrors
);

console.log(
    "========================================"
);


/* ============================================================
 * VALIDATION FAILED
 * ============================================================ */

if (!valid) {

    page.submitted = false;

    page.submitting = false;

    page.submitSuccess = false;

    page.submitError =
        "Please correct the highlighted fields before submitting.";


    console.log(
        "CLAIM SUBMISSION BLOCKED - VALIDATION FAILED"
    );

}


/* ============================================================
 * VALIDATION SUCCESS
 * ============================================================ */

else {

    page.submitted = true;

    page.submitting = true;

    page.submitSuccess = false;

    page.submitError = "";

page.claimUrl=
    bh.system.environment.properties.ssdURL +
    "createclaim";
    console.log(
        "CLAIM FORM VALIDATION SUCCESSFUL"
    );

    console.log(
        "Ready to call POST /claims"
    );



    bh.local.claimRequest = {

        policyNo:
            page.policyNo,

        customerName:
            page.customerName,

        vehicleRegistration:
            page.vehicleRegistration,

        vehicleType:
            page.vehicleType,

        yearOfManufacture:
            page.yearOfManufacture,

        idv:
            page.idv,

        policyStartDate:
            page.policyStartDate,

        policyEndDate:
            page.policyEndDate,

        policyStatus:
            page.policyStatus,

        dateOfLoss:
            page.dateOfLoss,

        lossType:
            page.lossType,

        primaryDamageGroup:
            page.primaryDamageGroup,

        estimatedPartsCost:
            page.estimatedPartsCost,

        garageType:
            page.garageType,

        firFiled:
            page.firFiled||false,

        validDrivingLicence:
            page.validDrivingLicence||false,

        lossDescription:
            page.lossDescription
    };


    console.log(
        "========== CREATE CLAIM REQUEST =========="
    );

    console.log(
        JSON.stringify(
            bh.local.claimRequest,
            null,
            2
        )
    );

}

console.log("pagee",page)

page.submitting = false;

page.submitSuccess = false;


// =====================================================
// GET STATUS
// =====================================================

let statusCode = 500;

if (
    bh.error &&
    bh.error.response &&
    bh.error.response.statusCode
) {

    statusCode =
        Number(
            bh.error.response.statusCode
        );
}


// =====================================================
// GET ERROR MESSAGE
// =====================================================

let errorMessage =
    String(
        bh.error?.message ||
        "Unable to create claim."
    );


// =====================================================
// FALLBACK STATUS FROM MESSAGE
// =====================================================

if (
    errorMessage.includes(
        "Response code 400"
    )
) {

    statusCode = 400;

}

else if (
    errorMessage.includes(
        "Response code 404"
    )
) {

    statusCode = 404;

}

else if (
    errorMessage.includes(
        "Response code 500"
    )
) {

    statusCode = 500;

}


// =====================================================
// USER MESSAGE
// =====================================================

if (statusCode === 400) {

    page.submitError =
        "Invalid claim request.";

}

else if (statusCode === 404) {

    page.submitError =
        "Claim service not found.";

}

else if (statusCode >= 500) {

    page.submitError =
        "Claim service is temporarily unavailable.";

}

else {

    page.submitError =
        "Unable to create claim.";

}


page.submitErrorStatus =
    statusCode;


console.log(
    "Error Status:",
    statusCode
);

console.log(
    "Error Message:",
    page.submitError
);

/* ============================================================
 * CREATE CLAIM API RESPONSE
 * ============================================================ */

console.log(
    "========== CREATE CLAIM API RESPONSE =========="
);

console.log(
    "API RESPONSE:",
    JSON.stringify(
        bh.local.createClaimResponse,
        null,
        2
    )
);


/* ============================================================
 * READ RESPONSE
 * ============================================================ */

const response =
    bh.local.createClaimResponse || {};


/* ============================================================
 * CHECK SUCCESS
 * ============================================================ */

if (response.success === true) {

    page.submitSuccess = true;
    page.submitting = false;
    page.submitted = true;
    page.submitError = "";

    /* --------------------------------------------------------
     * SAVE RESPONSE INTO PAGE VARIABLES
     * -------------------------------------------------------- */

    page.claimId =
        response.claimId || "";

    page.claimStatus =
        response.status || "";

    page.claimCreated =
        response.success;

    console.log(
        "Claim created successfully"
    );

    console.log(
        "Claim ID:",
        page.claimId
    );

    console.log(
        "Claim Status:",
        page.claimStatus
    );

}
else {

    page.submitSuccess = false;
    page.submitting = false;
    page.submitError =
        response.message ||
        "Unable to create claim.";

}


/* ============================================================
 * FINAL DEBUG
 * ============================================================ */

console.log(
    "========== PAGE CLAIM DATA =========="
);

console.log(
    "claimId:",
    page.claimId
);

console.log(
    "claimStatus:",
    page.claimStatus
);

console.log(
    "claimCreated:",
    page.claimCreated
);

console.log(
    "submitSuccess:",
    page.submitSuccess
);

console.log(
    "======================================"
);
